namespace sv_356145c4fe394a57928a3d6270c63eb5.Services;

public enum Theme
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service (one per circuit) that holds theme state and notifies subscribers on change.
/// </summary>
public class ThemeService
{
    private Theme _currentTheme = Theme.System;
    private string _accentColor = "#0d6efd";

    public Theme CurrentTheme
    {
        get => _currentTheme;
        set
        {
            if (_currentTheme == value) return;
            _currentTheme = value;
            NotifyStateChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyStateChanged();
        }
    }

    public event Action? OnChange;

    private void NotifyStateChanged() => OnChange?.Invoke();
}

@using sv_356145c4fe394a57928a3d6270c63eb5.Services
@rendermode InteractiveServer
@inject ThemeService ThemeService
@implements IDisposable

<span class="theme-indicator" style="color: @ThemeService.AccentColor;" title="Current theme">
    @GetThemeIcon() @ThemeService.CurrentTheme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += StateHasChanged;
    }

    private string GetThemeIcon() => ThemeService.CurrentTheme switch
    {
        Theme.Light => "☀️",
        Theme.Dark => "🌙",
        _ => "💻"
    };

    public void Dispose()
    {
        ThemeService.OnChange -= StateHasChanged;
    }
}

@using sv_356145c4fe394a57928a3d6270c63eb5.Services
@rendermode InteractiveServer
@inject ThemeService ThemeService
@implements IDisposable

<button class="btn btn-sm btn-outline-secondary" @onclick="CycleTheme"
        style="border-color: @ThemeService.AccentColor;">
    @GetThemeIcon()
</button>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += StateHasChanged;
    }

    private void CycleTheme()
    {
        ThemeService.CurrentTheme = ThemeService.CurrentTheme switch
        {
            Theme.Light => Theme.Dark,
            Theme.Dark => Theme.System,
            _ => Theme.Light
        };
    }

    private string GetThemeIcon() => ThemeService.CurrentTheme switch
    {
        Theme.Light => "☀️",
        Theme.Dark => "🌙",
        _ => "💻"
    };

    public void Dispose()
    {
        ThemeService.OnChange -= StateHasChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@using sv_356145c4fe394a57928a3d6270c63eb5.Services
@inject ThemeService ThemeService
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h3>User Preferences</h3>

<div class="card p-4" style="max-width: 500px; border-color: @ThemeService.AccentColor;">
    <div class="mb-3">
        <label class="form-label fw-bold">Theme</label>
        <div class="btn-group d-block" role="group">
            @foreach (var theme in Enum.GetValues<Theme>())
            {
                <button class="btn @(theme == ThemeService.CurrentTheme ? "btn-primary" : "btn-outline-primary")"
                        style="@(theme == ThemeService.CurrentTheme ? $"background-color: {ThemeService.AccentColor}; border-color: {ThemeService.AccentColor};" : "")"
                        @onclick="() => ThemeService.CurrentTheme = theme">
                    @theme
                </button>
            }
        </div>
    </div>

    <div class="mb-3">
        <label class="form-label fw-bold">Accent Color</label>
        <input type="color" class="form-control form-control-color"
               value="@ThemeService.AccentColor"
               @onchange="OnAccentColorChanged" />
        <small class="text-muted">Current: @ThemeService.AccentColor</small>
    </div>

    <div class="mt-3 p-3 rounded" style="background-color: @ThemeService.AccentColor; color: white;">
        Preview — Theme: @ThemeService.CurrentTheme | Accent: @ThemeService.AccentColor
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += StateHasChanged;
    }

    private void OnAccentColorChanged(ChangeEventArgs e)
    {
        ThemeService.AccentColor = e.Value?.ToString() ?? "#0d6efd";
    }

    public void Dispose()
    {
        ThemeService.OnChange -= StateHasChanged;
    }
}

